INSERT INTO `sys_notice` VALUES ('100001', '系统升级维护通知', '系统将于本周六凌晨2:00-6:00进行升级维护', '<h1>系统升级维护</h1><p>为了提供更好的服务，系统将于本周六凌晨2:00-6:00进行升级维护，期间部分功能可能无法正常使用。</p>', NULL, 'PLATFORM', 'SYSTEM_NOTICE', 'IMPORTANT', 'ENABLED', 1, 'YES', NULL, NULL, NULL, '2026-05-12 14:55:53.000', '50001', '2026-06-01 15:08:26.910', '50001');
INSERT INTO `sys_notice` VALUES ('100002', '欢迎使用 Hei FastAPI 系统', '欢迎各位同事使用全新开发的后台管理系统', '<p>Hei FastAPI 是一套基于 FastAPI + SQLAlchemy 2.0 的后台管理系统，欢迎大家体验并提供宝贵意见。</p>', NULL, 'PLATFORM', 'SYSTEM_NOTICE', 'NORMAL', 'ENABLED', 2, 'NO', NULL, NULL, NULL, '2026-05-12 14:55:53.000', '50001', '2026-05-12 14:55:53.000', '50001');
INSERT INTO `sys_notice` VALUES ('100003', '第三季度工作总结会议通知', '请各部门负责人准备第三季度工作总结报告', '<p>公司将于下周五召开第三季度工作总结会议，请各部门负责人准备相关材料。</p>', NULL, 'COMPANY', 'BUSINESS_NOTICE', 'IMPORTANT', 'ENABLED', 3, 'NO', NULL, NULL, NULL, '2026-05-12 14:55:53.000', '50001', '2026-06-01 15:44:09.843', '50001');
INSERT INTO `sys_notice` VALUES ('100004', '关于启用新系统的通知', '即日起正式启用全新后台管理系统', '<p>经过开发团队的不懈努力，全新后台管理系统已于今日正式上线，旧系统将并行运行一个月后下线。</p>', NULL, 'PLATFORM', 'SYSTEM_NOTICE', 'NORMAL', 'ENABLED', 4, 'NO', NULL, NULL, NULL, '2026-05-12 14:55:53.000', '50001', '2026-05-12 14:55:53.000', '50001');
